pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address attacker) public {
        vm.assume(caller != address(0) && attacker != address(0));
        vm.assume(caller != attacker);

        // Give some tokens to attacker so we can observe a decrease scenario
        vm.prank(caller);
        c.airDrop();

        uint256 attackerBalanceBefore = c.tokenBalance(attacker);

        // Have attacker call airdrop (should revert in reference since they already have tokens)
        vm.prank(attacker);
        (bool success, ) = address(c).call(abi.encodeWithSignature("airDrop()"));

        uint256 attackerBalanceAfter = c.tokenBalance(attacker);

        // General rule: token balance should never decrease
