    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address user) public {
        vm.assume(user != address(0));

        // Prepare: ensure user has no tokens and deal with bank issue
        // We need a Bank contract that returns the correct hash
        // Since Bank is not imported, we deploy it manually
        Bank bank = new Bank();
        vm.prank(user);
        // To satisfy supportsToken modifier, we need msg.sender to be a contract with supportsToken()
        // Since the test calls airDrop() directly, msg.sender is the test contract address
        // This doesn't satisfy the requirement, so we need to work around
